#include <iostream>
#include <string>

int main() {
    int a = 0;
    double b = 0.0;
    char c = '\0';
    std::string s;

    // Input contains: "  12 34.517ABC 12E D"
    if (std::cin >> a >> b >> c >> s) {
        std::cout << "a = " << a << "\n";
        std::cout << "b = " << b << "\n";
        std::cout << "c = '" << c << "'\n";
        std::cout << "s = \"" << s << "\"\n";
    }

    // Read the remaining queued string from the buffer
    std::string remaining;
    if (std::cin >> remaining) {
        std::cout << "remaining = \"" << remaining << "\"\n";
    }

    return 0;
}

#include <iostream>

int main() {
    char name[25];
    char hometown[30];

    // Read first field: stops before '\n'
    std::cin.get(name, 25);

    // Discard the leftover '\n' left behind by cin.get
    std::cin.get(); 

    // Read second field safely
    std::cin.get(hometown, 30);
    std::cin.ignore(1); // Discard the following '\n'

    std::cout << "Name: [" << name << "]\n";
    std::cout << "Hometown: [" << hometown << "]\n";

    // Chained character reading example
    char c1, c2;
    std::cin.get(c1).get(c2);
    std::cout << "Chars: '" << c1 << "', '" << c2 << "'\n";

    return 0;
}
